/* Local prototype journeys. No authentication, billing, AI, or publishing APIs. */
const baseRender=render;
const familyData=[['Editorial','A point of view, beautifully told.','olive'],['Minimal','Room for the work to breathe.','forma'],['Bold','A confident first impression.','offscript'],['Cinematic','Made for stories in motion.','offscript'],['Gallery','Let the images do the talking.','olive'],['Clean Professional','Clarity, with character.','forma']];
const blockTypes=['Project Intro','Big Image','Image Grid / Gallery','Text + Image','Challenge','Goal','Process','Concept','Research','Solution / Outcome','Before & After','Video Embed','Device / Mockup Showcase','Quote / Testimonial','Credits / Team','Next Project'];
const getProject=()=>state.projects.find(p=>p.id===projectId)||state.projects[0];
const dateText=t=>t?new Date(t).toLocaleDateString('en-GB',{day:'numeric',month:'short',timeZone:'Africa/Cairo'}):'Not published yet';
function appNav(){return `<aside class="app-nav"><button class="brand-button" data-action="go:overview">${logo()}</button><div class="workspace-label"><div class="avatar">${esc(state.profile.name.split(' ').map(w=>w[0]).slice(0,2).join(''))}</div><div><strong>${esc(state.profile.name)}</strong><small>Personal workspace</small></div></div><nav>${[['overview','home','Overview'],['editor','layers','Portfolio'],['projects','grid','Projects'],['analytics','chart','Analytics'],['publish','globe','Publish']].map(([v,i,n])=>`<button class="nav-row ${view===v?'active':''}" data-action="go:${v}">${icon(i)}${n}${v==='projects'?`<span class="badge">${state.projects.filter(p=>p.status!=='Archived').length}</span>`:''}</button>`).join('')}</nav><div class="app-nav-bottom"><div class="plan-note"><span class="eyebrow">YOUR PLAN</span><div class="row between"><strong>Free to create.</strong><span class="badge">FREE</span></div><p>One portfolio. All your potential.</p>${btn('Explore plans','upgrade:More room for your work','quiet')}</div><button class="nav-row" data-action="restart-onboarding">${icon('plus')}Try onboarding</button><button class="nav-row" data-action="account">${icon('settings')}Account & settings</button><button class="nav-row" data-action="theme">${icon('sun')}Switch appearance</button><div class="local-label">INTERACTIVE PROTOTYPE · LOCAL DATA</div></div></aside>`}
function appShell(content){return `<div class="app-shell">${appNav()}<main class="app-main"><div class="app-topline"><span>Your space to make an impression.</span><span class="row"><span class="saved">${icon('check')} Saved locally</span><span class="avatar">${esc(state.profile.name[0])}</span></span></div>${content}</main></div>`}
function overview(){let old=page,oldDevice=device;page='Home';device='desktop';const pf=portfolio(false,true);page=old;device=oldDevice;return appShell(`<div class="page-heading"><div><span class="eyebrow">YOUR CREATIVE HOME</span><h1>Good work deserves<br>a great <i class="editorial">portfolio.</i></h1><p>Welcome back, ${esc(state.profile.name.split(' ')[0])}. Make your next impression count.</p></div>${btn('Add project','quick-add','','plus')}</div><div class="overview-layout"><div><div class="overview-preview" data-action="go:editor" role="button" tabindex="0" aria-label="Open portfolio editor"><div class="browser-strip"><span>● ● ●</span><span>${esc(state.publish.slug)}.sitofolio.com</span><span>↗</span></div>${pf}</div></div><div class="overview-summary"><span class="status ${state.publish.status==='Published'?'published':''}">${state.publish.status}</span><h2>${esc(state.profile.name)}’s<br>portfolio</h2><p class="muted">${esc(state.style)} style family</p><div class="summary-divider"></div><div class="summary-line"><span>Last edited</span><strong>${state.updated?'Just recently':'Today'}</strong></div><div class="summary-line"><span>Portfolio views</span><strong>1,284 <small class="muted">demo</small></strong></div><div class="summary-line"><span>Projects</span><strong>${state.projects.filter(p=>p.status!=='Archived').length}</strong></div><div class="summary-divider"></div>${btn('Edit portfolio','go:editor','primary full','layers')}<div class="row" style="margin-top:10px">${btn('Preview','go:preview','grow','eye')}${btn('Publish','go:publish','grow')}</div><p class="help-tip" style="margin-top:16px">Saved changes stay private until you publish.</p></div></div><div class="section-heading row between"><h2>On your drawing board</h2><button class="text-button" data-action="go:projects">All projects ( ${state.projects.filter(p=>p.status!=='Archived').length} )</button></div><div class="library-grid compact-grid">${state.projects.filter(p=>p.status!=='Archived').slice(0,3).map(libraryCard).join('')}</div>`)}
function libraryCard(p){return `<article class="library-card">${projectCard(p)}<div class="row between"><span class="status ${p.status==='Published'?'published':''}">${esc(p.status)}</span><span class="small muted">Edited ${p.year}</span>${ib('more','project-menu:'+p.id,'Actions for '+p.title)}</div></article>`}
function projects(){const list=state.projects.filter(p=>(filter==='Archived'?p.status==='Archived':p.status!=='Archived')&&(filter==='All projects'||filter===p.status||filter===p.type)&&`${p.title} ${p.type}`.toLowerCase().includes(query.toLowerCase()));return appShell(`<div class="page-heading"><div><span class="eyebrow">THE COLLECTED WORK</span><h1>Your projects<span class="coral">.</span></h1><p>A home for everything you’re proud to put your name on.</p></div>${btn('Add project','quick-add','primary','plus')}</div><div class="library-toolbar"><label class="search">${icon('search')}<input aria-label="Search projects" placeholder="Find a project…" value="${esc(query)}" data-search></label><select aria-label="Filter projects" data-filter>${['All projects','Branding','UI/UX','Motion','Video','Photography','Other','Draft','Published','Hidden','Archived'].map(v=>`<option ${v===filter?'selected':''}>${v}</option>`).join('')}</select><span class="small muted">${list.length} projects</span></div><div class="library-grid">${list.map(libraryCard).join('')}</div>${!list.length?`<div class="empty"><h2>${query?'No projects found.':'Your best work goes here.'}</h2><p>${query?'Try another title or category.':'Start with a title, a cover, and a few rough notes.'}</p>${btn('Add your first project','quick-add','primary')}</div>`:''}`)}
function analytics(){return appShell(`<div class="page-heading"><div><span class="eyebrow">A LITTLE PERSPECTIVE</span><h1>Your work is<br>getting <i class="editorial">noticed.</i></h1><p>Sample analytics · Last 30 days</p></div><span class="badge">DEMO DATA</span></div><div class="analytics-numbers"><div><span>Total views</span><strong>1,284</strong><small>+18% from last month</small></div><div><span>Unique visitors</span><strong>862</strong><small>People finding your work</small></div><div><span>Contact clicks</span><strong>24</strong><small>Conversations waiting to happen</small></div></div><div class="analytics-chart" role="img" aria-label="Sample daily views chart, increasing from 18 to 72 views over 30 days">${[18,23,21,31,25,34,29,40,35,45,40,46,31,34,44,58,52,49,62,58,51,64,68,55,63,70,59,66,73,72].map(v=>`<div style="height:${v}%"></div>`).join('')}</div><div class="row between muted small"><span>30 days ago</span><span>Today</span></div><div class="analytics-bottom"><div><h2>Work that connects</h2>${state.projects.slice(0,3).map((p,i)=>`<button class="rank-row" data-action="project:${p.id}"><span>0${i+1}</span><strong>${esc(p.title)}</strong><span>${[542,381,219][i]} views</span></button>`).join('')}</div><div><h2>How they found you</h2>${[['Direct','46%'],['Instagram','32%'],['Search','14%'],['Other','8%']].map(([n,v])=>`<div class="rank-row"><strong>${n}</strong><span>${v}</span></div>`).join('')}</div></div>`)}
function recommended(){const o=state.onboarding;const score={Minimal:0,Editorial:1,Bold:0,Cinematic:0,Gallery:0,'Clean Professional':0};if(/Motion|Video/.test(o.role))score.Cinematic+=5;if(o.role==='Photographer')score.Gallery+=5;if(o.role==='UI/UX Designer')score['Clean Professional']+=4;if(/hired|agencies/.test(o.goal))score['Clean Professional']+=2;for(const p of o.personality){score[{Clean:'Clean Professional',Experimental:'Bold'}[p]||p]+=3}return [...familyData].sort((a,b)=>score[b[0]]-score[a[0]]).slice(0,3)}
function styleCard(f){const p=state.projects.find(p=>p.id===f[2])||initial.projects.find(p=>p.id===f[2]);return `<button class="style-card ${state.style===f[0]?'selected':''}" data-action="choose-style:${f[0]}" aria-pressed="${state.style===f[0]}"><div class="style-example style-${f[0].toLowerCase().replace(' ','-')}"><span>${esc(state.profile.name)}®</span><h3>${f[0]==='Editorial'?'A different<br><i>point of view.</i>':f[0]==='Minimal'?'Less noise.<br>More meaning.':f[0]==='Bold'?'MAKE<br>YOUR MARK.':f[0]==='Cinematic'?'Stories<br>in motion.':f[0]==='Gallery'?'A closer look.':'Considered.<br>Connected.'}</h3><img src="${p.cover}" alt="${f[0]} portfolio example"></div><div class="style-card-bottom"><div><h3>${f[0]}</h3><p>${f[1]}</p></div><span class="radio-check">${state.style===f[0]?'✓':''}</span></div></button>`}
function onboarding(){const step=state.onboarding.step;const titles=['A small hello.<br>A bigger <i class="editorial">possibility.</i>','What kind of<br>work do you make?','What’s next<br>for your work?','What feels<br>like <i class="editorial">you?</i>','Put your name<br>on it.','Start with something<br>you’re proud of.','Your work.<br>Your words.','A starting point.<br>Not a <i class="editorial">limit.</i>'];let body='';
if(step===0)body=`<p class="intro-copy">Your work has a point of view.<br>Your portfolio should, too.</p><div class="account-demo"><span class="badge">NO ACCOUNT NEEDED FOR THIS PROTOTYPE</span>${btn('Continue with demo profile','onboard-next','primary full')}<p class="help-tip">Explore the experience with sample work. Everything you change stays in this browser.</p></div>`;
if(step===1)body=`<p class="intro-copy">We’ll find a good home for the things you create.</p><div class="choice-grid">${['Graphic Designer','UI/UX Designer','Motion Designer','Video Editor','Photographer','Other'].map((v,i)=>`<button class="choice ${state.onboarding.role===v?'selected':''}" data-action="role:${v}" aria-pressed="${state.onboarding.role===v}"><span class="choice-icon">${icon(['type','desktop','layers','image','image','grid'][i])}</span><span>${v}</span><span class="radio-check">${state.onboarding.role===v?'✓':''}</span></button>`).join('')}</div>`;
if(step===2)body=`<p class="intro-copy">Let’s give your portfolio a little direction.</p><div class="goal-list">${['Get hired','Get freelance clients','Build my personal brand','Showcase my work','Apply to agencies / studios'].map(v=>`<button class="choice ${state.onboarding.goal===v?'selected':''}" data-action="goal:${v}" aria-pressed="${state.onboarding.goal===v}">${v}<span class="radio-check">${state.onboarding.goal===v?'✓':''}</span></button>`).join('')}</div>`;
if(step===3)body=`<p class="intro-copy">Pick one or two. Think instinct, not a commitment.</p><div class="personality-grid">${['Minimal','Bold','Editorial','Cinematic','Clean','Experimental'].map((v,i)=>`<button class="personality ${state.onboarding.personality.includes(v)?'selected':''} personality-${v.toLowerCase()}" data-action="personality:${v}" aria-pressed="${state.onboarding.personality.includes(v)}"><div class="personality-art">${['Aa.','Aa!','<i>Aa.</i>','Aa.','Aa.','A/a'][i]}</div><span>${v}</span></button>`).join('')}</div>`;
if(step===4)body=`<p class="intro-copy">Just the essentials. You can fill in the rest later.</p><div class="profile-form">${field('Your name','profile.name',state.profile.name)}${field('Professional title','profile.title',state.profile.title)}${field('Short bio · optional','profile.bio',state.profile.bio,'textarea')}${btn('Help me write a bio','bio-ai','ai')}${field('Location · optional','profile.location',state.profile.location)}</div>`;
if(step===5)body=`<p class="intro-copy">A few notes and a great image are all you need.</p><div class="onboard-project">${cover(state.projects[0])}<div><span class="eyebrow">YOUR FIRST PROJECT</span><h3>${esc(state.projects[0].title)}</h3><p>${esc(state.projects[0].notes)}</p>${btn('Add your own project','quick-add','','plus')}</div></div><p class="help-tip">Sample projects are here to help you explore. Keep them, replace them, or skip for now.</p>`;
if(step===6)body=`<p class="intro-copy">A little help turning your notes into a story.<br>You always have the final say.</p><div class="onboard-ai"><span class="ai-dot">AI ASSIST</span><h3>Less staring at a blank page.</h3><p>Get an editable project introduction and a suggested structure, based on your work.</p><div class="row">${btn('Help me structure it','onboard-ai','ai')}${btn('Build it myself','onboard-next')}</div>${aiDraft?`<div class="draft-preview"><span class="eyebrow">EDITABLE DRAFT · SIMULATED AI</span><p>${esc(aiDraft)}</p></div>`:''}</div>`;
if(step===7)body=`<p class="intro-copy">Three style families for your point of view.<br>Every detail is yours to make your own.</p><div class="recommendation-meta"><span>${esc(state.onboarding.role)}</span><span>${esc(state.onboarding.personality.join(' + '))}</span><button class="text-button" data-action="onboard-back">Refine choices</button></div><div class="styles-grid">${(showAllStyles?familyData:recommended()).map(styleCard).join('')}</div><button class="text-button" data-action="all-styles">${showAllStyles?'Show recommendations':'View all 6 style families'}</button>`;
return `<div class="onboarding"><header class="onboard-top"><button data-action="go:overview">${logo()}</button><div class="onboard-progress">${['You','Your work','Your style'].map((s,i)=>`<span class="${step>=[1,5,7][i]?'active':''}">${String(i+1).padStart(2,'0')} <b>${s}</b></span>`).join('')}</div>${btn('Back to workspace','go:overview','quiet')}</header><main class="onboard-main ${step===7?'wide':''}"><span class="eyebrow">${step===7?'CURATED FOR YOU':`LET’S MAKE IT YOURS · ${String(step+1).padStart(2,'0')} / 08`}</span><h1>${titles[step]}</h1>${body}</main><footer class="onboard-footer">${step?btn('Back','onboard-back','quiet','back'):'<span></span>'}<span class="help-tip">${step===7?'Style is a starting point. Your content stays yours.':'About two minutes. A whole new perspective.'}</span><div class="row">${[5,6].includes(step)?btn('Skip for now','onboard-next','quiet'):''}${step>0?btn(step===7?'Make it mine':'Continue',step===7?'finish-onboard':'onboard-next','primary'):''}</div></footer></div>`}
function projectBuilder(){const p=getProject();if(!p)return projects();return `<header class="topbar"><button class="row" data-action="go:projects">${icon('back')}${logo()}</button><span class="separator"></span><span class="crumb">Projects <span class="muted">/ ${esc(p.title)}</span></span><div class="grow"></div><span class="saved">${icon('check')} Saved locally</span><span class="status">${esc(p.status)}</span>${btn('Preview project','preview-project:'+p.id,'','eye')}${btn('Done','go:projects','primary')}${ib('sun','theme','Toggle light and dark interface')}</header><main class="builder-shell"><aside class="left-panel"><div class="panel-block"><span class="eyebrow">PROJECT STORY</span><h3>${esc(p.title)}</h3><p class="help-tip" style="margin-top:8px">${esc(p.type)} · ${p.blocks.length} blocks</p></div><div class="builder-block-list">${p.blocks.map((b,i)=>`<div class="section-row ${selectedBlock===b.id?'active':''} ${!b.visible?'hidden-section':''}" draggable="true" data-drag-block="${b.id}"><button data-action="select-block:${b.id}"><span class="muted small">${String(i+1).padStart(2,'0')}</span>${esc(b.type)}</button>${ib('eye','toggle-block:'+b.id,'Toggle '+b.type+' visibility')}</div>`).join('')}</div><div class="panel-block">${btn('Add block','add-block','full','plus')}</div><div class="panel-foot"><button class="nav-row" data-action="project-details">${icon('settings')}Project details</button><button class="nav-row" data-action="project-settings">${icon('lock')}Visibility & status</button></div></aside><div class="builder-canvas"><div class="case-heading"><span class="eyebrow">${esc(p.type)} · ${esc(p.year)}</span><h1 contenteditable="true" data-case-edit="title" aria-label="Project title">${esc(p.title)}</h1><div class="row muted small"><span>${esc(p.role)}</span><span>·</span><button class="text-button" data-action="project-details">Edit details</button></div></div><div class="case-cover">${cover(p)}<button class="btn replace-cover" data-action="replace-cover">${icon('image')}Replace cover</button></div>${p.blocks.filter(b=>b.visible).map((b,i)=>`<section class="case-block ${selectedBlock===b.id?'selected':''}" id="block-${b.id}" data-case-block="${b.id}"><div class="block-controls"><span class="eyebrow">${String(i+1).padStart(2,'0')} / ${esc(b.type)}</span><span class="row">${ib('up','move-block:'+b.id+':-1','Move '+b.type+' up')}${ib('down','move-block:'+b.id+':1','Move '+b.type+' down')}${ib('copy','duplicate-block:'+b.id,'Duplicate '+b.type)}${ib('trash','delete-block:'+b.id,'Delete '+b.type)}</span></div>${renderBlock(b,p,true)}</section>`).join('')}${btn('Add to the story','add-block','full','plus')}</div><aside class="right-panel assistant-panel"><div class="prop-head"><h3>Your writing partner</h3><span class="ai-dot">AI</span></div><div class="panel-block"><span class="eyebrow">START WITH YOUR NOTES</span>${field('What’s the story?','project.notes',p.notes,'textarea')}<p class="help-tip">Write like you’re telling a friend. We’ll help with the rest.</p></div><div class="panel-block"><div class="eyebrow">A LITTLE ASSISTANCE</div>${[['description','Generate description'],['structure','Structure my notes'],['shorter','Make shorter'],['professional','Make more professional'],['order','Suggest section order']].map(([id,t])=>`<button class="ai-action" data-action="ai:${id}"><span>${t}</span>${icon('plus')}</button>`).join('')}</div><div class="panel-block"><div class="ai-output"><span class="eyebrow">${aiDraft?'YOUR EDITABLE DRAFT':'YOU’RE STILL THE AUTHOR'}</span>${aiDraft?`<textarea aria-label="AI draft" data-ai-draft>${esc(aiDraft)}</textarea><div class="row">${btn('Use draft','apply-ai','ai')}${btn('Dismiss','dismiss-ai','quiet')}</div>`:'<p>Pick an action above. Suggestions will appear here for you to edit and review.</p>'}</div><p class="help-tip" style="margin-top:14px">Simulated AI for this prototype. Suggestions are never published automatically.</p></div></aside></main>`}
function renderBlock(b,p,edit=false){const img=['Big Image','Device / Mockup Showcase'].includes(b.type);if(img)return `<img class="block-image" src="${esc(b.image||p.cover)}" alt="${esc(b.alt||p.title+' visual')}" ${edit?'data-action="block-image:'+b.id+'" tabindex="0" role="button" aria-label="Replace block image"':''}>`;
if(['Image Grid / Gallery','Before & After'].includes(b.type))return `<div class="block-gallery"><img src="${esc(b.image||p.cover)}" alt="${esc(b.alt||p.title+' first image')}"><img src="${esc(b.secondImage||initial.projects.find(x=>x.id!==p.id).cover)}" alt="${esc(b.secondAlt||'Second project image')}"></div>${edit?btn('Edit gallery images','gallery-images:'+b.id,'quiet'):''}`;
if(b.type==='Text + Image')return `<div class="text-image"><p ${edit?'contenteditable="true" data-block-edit="'+b.id+'"':''}>${esc(b.text)}</p><img src="${esc(b.image||p.cover)}" alt="${esc(b.alt||p.title)}"></div>`;
if(b.type==='Video Embed')return `<div class="video-placeholder">${icon('image')}<p>${b.url?'Video reference: '+esc(b.url):'Add a link to your showreel.'}</p>${edit?btn('Set video URL','video-url:'+b.id):b.url?`<a class="btn" href="${esc(b.url)}" target="_blank" rel="noopener">Watch video</a>`:''}</div>`;
if(b.type==='Next Project'){const next=state.projects.find(x=>x.id!==p.id&&x.status!=='Archived');return next?projectCard(next,edit?'project:':'preview-project:'):'<p>Add another project to connect the story.</p>'}
return `<h2>${b.type==='Project Intro'?'The idea.':esc(b.type)}</h2><${b.type==='Quote / Testimonial'?'blockquote':'p'} ${edit?'contenteditable="true" data-block-edit="'+b.id+'" aria-label="'+esc(b.type)+' text"':''}>${esc(b.text||'Tell this part of the story…')}</${b.type==='Quote / Testimonial'?'blockquote':'p'}>`}
function casePreview(){const p=state.projects.find(p=>p.id===activePreviewProject)||getProject();return `<article class="portfolio case-preview ${device}"><div class="pf-nav"><button class="pf-name" data-action="preview-home">${esc(state.profile.name)}</button><button class="text-button" data-action="preview-home">All work</button></div><div class="case-heading"><span class="eyebrow">${esc(p.type)} · ${esc(p.year)}</span><h1>${esc(p.title)}</h1><p>${esc(p.role)}</p></div>${cover(p)}${p.blocks.filter(b=>b.visible).map(b=>`<section class="case-block">${renderBlock(b,p)}</section>`).join('')}<div class="pf-footer"><span>© 2026 ${esc(state.profile.name)}</span><span>Made with Sitofolio</span></div></article>`}
function publishPanel(){return `<aside class="publish-panel"><span class="eyebrow">READY WHEN YOU ARE</span><h2>A little closer<br>to <i class="editorial">out there.</i></h2><p class="muted">Give your work a home.</p><form id="publish-form"><div class="publish-step"><span class="step-number">01</span><div><h3>Your address</h3><label class="field"><span>Sitofolio subdomain</span><div class="domain-input"><input data-field="publish.slug" value="${esc(state.publish.slug)}" aria-label="Subdomain" required pattern="[a-z0-9]+(?:-[a-z0-9]+)*" maxlength="30"><span>.sitofolio.com</span></div></label><button type="button" class="text-button" data-action="upgrade:Custom domains"><span>Use your own domain</span> <span class="badge">SOLO</span></button></div></div><div class="publish-step"><span class="step-number">02</span><div><h3>A good first impression</h3>${field('Page title','publish.seoTitle',state.publish.seoTitle)}${field('Description','publish.description',state.publish.description,'textarea')}<div class="search-preview"><span>${esc(state.publish.slug)}.sitofolio.com</span><strong>${esc(state.publish.seoTitle)}</strong><p>${esc(state.publish.description)}</p></div></div></div><details><summary>More settings</summary>${selectField('Portfolio language','publish.language',state.publish.language,['English','Arabic','French','German'])}<label class="check-row"><input type="checkbox" data-publish-check="search" ${state.publish.search?'checked':''}>Show in search engines</label><label class="check-row"><input type="checkbox" data-publish-check="analytics" ${state.publish.analytics?'checked':''}>Enable analytics</label><p class="help-tip">These settings are simulated in this prototype.</p></details><div class="publish-status"><span class="status ${state.publish.status==='Published'?'published':''}">${state.publish.status}</span><span class="small muted">${dateText(state.publish.last)}</span></div><button type="submit" class="btn primary full">${state.publish.status==='Published'?'Publish changes':'Publish portfolio'}</button><p class="help-tip" style="margin-top:12px;text-align:center">Prototype only. No website will go live.</p></form>${state.publish.status==='Published'?btn('View published version','published-preview','full quiet'):''}</aside>`}
let publishedPreview=false;
function preview(){let output;if(publishedPreview&&state.publish.snapshot){const live=state;state=structuredClone(state.publish.snapshot);output=activePreviewProject?casePreview():portfolio(false);state=live}else output=activePreviewProject?casePreview():portfolio(false);return `<header class="topbar"><button class="row" data-action="go:editor">${icon('back')}<span>Back to editor</span></button><span class="separator"></span><span class="crumb">${publishedPreview?'Published snapshot':'Portfolio preview'}</span><div class="grow"></div>${deviceControls()}${view==='preview'?btn('Ready to publish','go:publish','primary'):btn('Preview only','go:preview','quiet')}${ib('sun','theme','Toggle light and dark interface')}</header><main class="preview-shell ${view==='publish'?'with-publish':''}"><div class="preview-canvas"><div class="preview-address">${icon('lock')} ${esc(state.publish.slug)}.sitofolio.com <span class="badge">${publishedPreview?'LOCAL PUBLISHED SNAPSHOT':'PRIVATE PREVIEW'}</span></div>${output}</div>${view==='publish'?publishPanel():''}</main>`}
render=function(){document.body.classList.toggle('dark',localStorage.getItem('sitofolio-theme')==='dark');if(view==='editor'){baseRender();return}app.innerHTML=view==='overview'?overview():view==='projects'?projects():view==='analytics'?analytics():view==='onboarding'?onboarding():view==='project'?projectBuilder():['preview','publish'].includes(view)?preview():overview()};
function modal(title,body,actions=''){const d=$('#dialog');d.setAttribute('aria-labelledby','dialog-title');d.innerHTML=`<div class="dialog-head row between"><h2 id="dialog-title">${title}</h2>${ib('close','close-dialog','Close dialog')}</div>${body}${actions?`<div class="dialog-actions">${actions}</div>`:''}`;if(!d.open)d.showModal()}
function closeModal(){$('#dialog').close();render()}
function quickAdd(){modal('Make room for your next idea.',`<p class="muted" style="margin-bottom:24px">Start small. You can build the full story afterwards.</p><form id="quick-form"><div class="form-grid"><label class="field span2"><span>Project title</span><input name="title" placeholder="A name worth remembering" required autofocus></label><label class="field"><span>Project type</span><select name="type">${['Branding','UI/UX','Motion','Video','Photography','Other'].map(v=>`<option>${v}</option>`).join('')}</select></label><label class="field"><span>Year</span><input name="year" type="number" min="1900" max="2100" value="2026" required></label><label class="field span2"><span>Your role</span><input name="role" placeholder="Art direction, design, photography…" value="Design & art direction"></label><label class="field span2"><span>A few rough notes</span><textarea name="notes" placeholder="What was the project? What did you bring to it?"></textarea></label><label class="field span2"><span>Cover image · optional</span><input name="cover" type="file" accept="image/png,image/jpeg,image/webp"><small>PNG, JPG or WebP, up to 3 MB. A sample cover is used if skipped.</small></label></div><div class="dialog-actions">${btn('Cancel','close-dialog','quiet')}<button class="btn primary" type="submit">Create project</button></div></form>`)}
function addBlock(){modal('Tell the story your way.',`<p class="muted" style="margin-bottom:20px">Pick a block. Keep only what your project needs.</p><div class="block-picker">${blockTypes.map(b=>`<button class="choice" data-action="insert-block:${b}">${icon(/Image|Gallery|Mockup/.test(b)?'image':'type')}${b}${icon('plus')}</button>`).join('')}</div>`)}
function upgrade(context){modal('A little more room to grow.',`<span class="badge">${esc(context)}</span><p class="muted" style="margin:16px 0 24px">${esc(context)} ${context==='Password protection'?'is available on Pro.':context==='Custom domains'?'are available on Solo.':'is available on Solo.'} Your work stays right where it is.</p><div class="plans"><div><span class="eyebrow">SOLO</span><h3>249 <small>EGP / month</small></h3><p>Custom domain<br>Remove Sitofolio branding<br>More projects & storage<br>All core style families</p></div><div><span class="eyebrow">PRO</span><h3>449 <small>EGP / month</small></h3><p>Everything in Solo<br>Password-protected projects<br>Higher AI limits<br>Advanced analytics</p></div></div><p class="help-tip" style="margin-top:20px">Indicative prototype pricing. No payment is collected and no subscription is created.</p>`,btn('Keep creating','close-dialog','primary'))}
function projectMenu(id){const p=state.projects.find(x=>x.id===id);modal(esc(p.title),`<div class="menu-list">${btn('Edit project','project:'+id,'full','layers')}${btn('Duplicate','duplicate-project:'+id,'full','copy')}${btn(p.status==='Hidden'?'Show project':'Hide project','hide-project:'+id,'full','eye')}${btn(p.status==='Archived'?'Restore project':'Archive project','archive-project:'+id,'full','layers')}</div>`)}
function sectionOptions(){const s=state.sections.find(x=>x.id===selected);if(!s)return;modal(esc(s.type),`<div class="menu-list">${btn('Move up','move-section:-1','full','up')}${btn('Move down','move-section:1','full','down')}${btn('Duplicate section','duplicate-section','full','copy')}${btn('Delete section','delete-section','full','trash')}</div>`)}
function assets(){modal('Your creative material.',`<p class="muted">Images stay in this browser, ready to use.</p><label class="upload-zone">${icon('upload')}<span>Add image</span><input type="file" accept="image/png,image/jpeg,image/webp" data-upload-asset><small>Up to 3 MB per image</small></label><div class="asset-grid">${[...state.projects.map(p=>({name:p.title,url:p.cover})),...state.assets].map(a=>`<figure><img src="${esc(a.url)}" alt="${esc(a.name)}"><figcaption>${esc(a.name)}</figcaption></figure>`).join('')}</div>`)}
function projectDetails(){const p=getProject();modal('The details behind the work.',`<div class="form-grid">${field('Title','project.title',p.title)}${selectField('Type','project.type',p.type,['Branding','UI/UX','Motion','Video','Photography','Other'])}${field('Year','project.year',p.year)}${field('Role','project.role',p.role)}${field('Client · optional','project.client',p.client||'')}${field('Industry · optional','project.industry',p.industry||'')}${field('Tools · optional','project.tools',p.tools||'')}${field('Duration · optional','project.duration',p.duration||'')}<div class="span2">${field('Cover alt text','project.alt',p.alt||p.title+' — '+p.type+' project')}</div></div>`,btn('Done','close-dialog','primary'))}
function projectSettings(){const p=getProject();modal('Who gets to see it?',`${selectField('Project status','project.status',p.status,['Draft','Published','Hidden'])}${selectField('Visibility','project.visibility',p.visibility,['Public','Private','Password protected'])}<p class="help-tip">Private projects are excluded from published snapshots. Password protection is a Pro feature.</p><label class="check-row" style="margin-top:20px"><input type="checkbox" data-feature="${p.id}" ${p.featured?'checked':''}>Feature on homepage</label>`,btn('Done','close-dialog','primary'))}
function uploadDialog(title,attrs,alt=''){modal(title,`<label class="upload-zone">${icon('upload')}<span>Choose an image</span><input type="file" accept="image/png,image/jpeg,image/webp" ${attrs}><small>PNG, JPG or WebP · up to 3 MB</small></label>${alt}`,btn('Done','close-dialog','primary'))}
function structureFor(type){return type==='UI/UX'?['Project Intro','Challenge','Research','Process','Solution / Outcome','Device / Mockup Showcase']:['Motion','Video'].includes(type)?['Project Intro','Concept','Image Grid / Gallery','Video Embed','Credits / Team']:type==='Photography'?['Project Intro','Image Grid / Gallery','Credits / Team']:['Project Intro','Challenge','Concept','Big Image','Solution / Outcome']}
function suggestion(action,p){const notes=p.notes.trim();if(action==='order')return structureFor(p.type).join(' → ');if(action==='structure')return `${p.title}\n\n${notes||'Add a few notes about the project to make this draft more personal.'}\n\nSuggested story: ${structureFor(p.type).join(' → ')}`;if(action==='shorter')return notes?notes.split(/[.!?]/).filter(Boolean).slice(0,1).join('.')+'.':`${p.title}: a ${p.type.toLowerCase()} project by ${state.profile.name}.`;if(action==='professional')return `${p.title} is a ${p.type.toLowerCase()} project focused on a clear, considered visual direction. ${notes} My contribution covered ${p.role.toLowerCase()}.`;return `${p.title} — ${notes||'A considered exploration of identity, purpose, and visual expression.'}\n\nWorking across ${p.role.toLowerCase()}, I developed a ${p.type.toLowerCase()} approach with a distinctive point of view.`}
function handleExtraAction(action,v){
if(action==='restart-onboarding'){state.onboarding.step=0;save();go('onboarding');return}if(action==='quick-add'){quickAdd();return}if(action==='close-dialog'){closeModal();return}if(action==='upgrade'){upgrade(v);return}if(action==='page-menu'){leftTab='Pages';render();return}if(action==='project'){closeModal();projectId=v;selectedBlock=null;aiDraft='';go('project');return}if(action==='project-menu'){projectMenu(v);return}
if(action==='preview-project'){activePreviewProject=v;go('preview');return}if(action==='preview-home'){activePreviewProject=null;page='Work';render();return}if(action==='published-preview'){publishedPreview=true;activePreviewProject=null;page='Home';go('preview');return}
if(action==='duplicate-project'){mutate(()=>{const p=structuredClone(state.projects.find(p=>p.id===v));p.id=crypto.randomUUID();p.title+=' — Copy';p.status='Draft';state.projects.push(p)});closeModal();toast('Project duplicated.');return}
if(action==='hide-project'||action==='archive-project'){mutate(()=>{const p=state.projects.find(p=>p.id===v);p.status=action==='hide-project'?(p.status==='Hidden'?'Draft':'Hidden'):(p.status==='Archived'?'Draft':'Archived')});closeModal();toast('Project updated.',true);return}
if(action==='section-options'){sectionOptions();return}if(action==='add-section'){modal('Make it your own.',`<div class="block-picker">${['Hero','Selected Work','About','Services / Skills','Experience','Testimonials','Clients','Contact','Footer'].map(t=>btn(t,'insert-section:'+t,'full','plus')).join('')}</div>`);return}
if(action==='insert-section'){mutate(()=>{const s={id:crypto.randomUUID(),type:v,visible:true,text:''};state.sections.splice(Math.max(0,state.sections.length-1),0,s);selected=s.id});closeModal();toast('Section added.',true);return}
if(['duplicate-section','delete-section','move-section'].includes(action)){mutate(()=>{const i=state.sections.findIndex(s=>s.id===selected);if(i<0)return;if(action==='delete-section'){state.sections.splice(i,1);selected=null}else if(action==='duplicate-section'){const s={...state.sections[i],id:crypto.randomUUID()};state.sections.splice(i+1,0,s);selected=s.id}else{const to=Math.max(0,Math.min(state.sections.length-1,i+Number(v)));state.sections.splice(to,0,state.sections.splice(i,1)[0])}});closeModal();toast('Sections updated.',true);return}
if(action==='hero-image'){uploadDialog('A different point of view.','data-hero-image',field('Alt text','heroImageAlt',state.heroImageAlt||'Featured creative work'));return}if(action==='assets'){assets();return}if(action==='project-details'){projectDetails();return}if(action==='project-settings'){projectSettings();return}if(action==='replace-cover'){uploadDialog('A new first impression.','data-replace-cover');return}
if(action==='add-block'){addBlock();return}if(action==='insert-block'){mutate(()=>{const b={id:crypto.randomUUID(),type:v,text:'',visible:true};getProject().blocks.push(b);selectedBlock=b.id});closeModal();toast('Block added.',true);return}
if(action==='select-block'){selectedBlock=v;render();$('#block-'+v)?.scrollIntoView({block:'center',behavior:'smooth'});return}
if(['toggle-block','duplicate-block','delete-block','move-block'].includes(action)){const [id,dir]=v.split(':');mutate(()=>{let a=getProject().blocks,i=a.findIndex(b=>b.id===id);if(i<0)return;if(action==='toggle-block')a[i].visible=!a[i].visible;if(action==='duplicate-block')a.splice(i+1,0,{...a[i],id:crypto.randomUUID()});if(action==='delete-block')a.splice(i,1);if(action==='move-block'){const to=Math.max(0,Math.min(a.length-1,i+Number(dir)));a.splice(to,0,a.splice(i,1)[0])}});toast('Story updated.',true);return}
if(action==='block-image'){uploadDialog('Replace block image.',`data-block-image="${v}"`,field('Alt text','block.'+v+'.alt',getProject().blocks.find(b=>b.id===v).alt||''));return}
if(action==='gallery-images'){modal('Two images. One story.',`<label class="field"><span>First image</span><input type="file" accept="image/png,image/jpeg,image/webp" data-block-image="${v}"></label><label class="field"><span>Second image</span><input type="file" accept="image/png,image/jpeg,image/webp" data-block-second="${v}"></label>`,btn('Done','close-dialog','primary'));return}
if(action==='video-url'){const b=getProject().blocks.find(x=>x.id===v);modal('Link your film.',`${field('Video URL','block.'+v+'.url',b.url||'','url','YouTube and Vimeo links play inline. Other HTTPS videos open in a new tab.')}`,btn('Done','close-dialog','primary'));return}
if(action==='ai'){aiDraft=suggestion(v,getProject());render();return}if(action==='dismiss-ai'){aiDraft='';render();return}if(action==='apply-ai'){const draft=$('[data-ai-draft]')?.value||aiDraft;mutate(()=>{let b=getProject().blocks.find(x=>x.id===selectedBlock&& !/Image|Gallery|Video|Mockup/.test(x.type))||getProject().blocks.find(x=>x.type==='Project Intro');if(!b){b={id:crypto.randomUUID(),type:'Project Intro',visible:true};getProject().blocks.unshift(b)}b.text=draft;aiDraft=''});toast('Draft added. Edit it directly in your story.',true);return}
if(['role','goal'].includes(action)){mutate(()=>state.onboarding[action]=v);return}if(action==='personality'){mutate(()=>{const a=state.onboarding.personality;if(a.includes(v))a.splice(a.indexOf(v),1);else if(a.length<2)a.push(v);else{a.shift();a.push(v)}});return}
if(action==='onboard-next'){const o=state.onboarding;if(o.step===3&&!o.personality.length){toast('Choose at least one visual personality.');return}if(o.step===4&&(!state.profile.name.trim()||!state.profile.title.trim())){toast('Add your name and professional title.');return}mutate(()=>o.step=Math.min(7,o.step+1));window.scrollTo(0,0);return}
if(action==='onboard-back'){mutate(()=>state.onboarding.step=Math.max(0,state.onboarding.step-1));return}if(action==='onboard-ai'){aiDraft=suggestion('structure',state.projects[0]);render();return}if(action==='all-styles'){showAllStyles=!showAllStyles;render();return}
if(action==='choose-style'){mutate(()=>applyFamily(v));return}if(action==='finish-onboard'){mutate(()=>state.onboarding.complete=true);page='Home';go('editor');toast('Make yourself at home. Your portfolio is ready to edit.');return}
if(action==='bio-ai'){modal('A starting point for your bio.',`<span class="ai-dot">EDITABLE DRAFT · SIMULATED AI</span><label class="field" style="margin-top:20px"><span>Suggested bio</span><textarea id="bio-draft">${esc('I’m '+state.profile.name+', '+state.profile.title.toLowerCase()+'. I help ambitious people turn ideas into thoughtful visual experiences. '+(state.profile.location?'Based in '+state.profile.location+'.':''))}</textarea></label>`,btn('Cancel','close-dialog','quiet')+btn('Use this draft','apply-bio','ai'));return}
if(action==='apply-bio'){mutate(()=>state.profile.bio=$('#bio-draft').value);closeModal();return}
if(action==='account'){modal('Your corner of the internet.',`${field('Name','profile.name',state.profile.name)}${field('Professional title','profile.title',state.profile.title)}${field('Contact email','profile.email',state.profile.email,'email')}<p class="help-tip">This is a local demo profile. Authentication and billing are outside this prototype.</p>`,btn('Done','close-dialog','primary'));return}
if(action==='preview-link'){modal('A private look at your work.', '<p class="muted">This local preview includes your latest saved changes.</p><label class="field" style="margin-top:20px"><span>Preview link</span><input readonly value="'+location.origin+'/#preview"></label><p class="help-tip">Works on this computer. Shareable cloud review links will be connected in the MVP.</p>',btn('Copy local link','copy-preview-link','primary'));return}if(action==='copy-preview-link'){navigator.clipboard.writeText(location.origin+'/#preview').then(()=>toast('Local preview link copied.')).catch(()=>toast('Select the preview link and copy it manually.'));return}
}
function applyFamily(v){state.style=v;state.palette=v==='Cinematic'?'ink':'ivory';state.heroVariant=v==='Bold'?'Statement':v==='Clean Professional'?'Split':v==='Minimal'?'Editorial':'Editorial';state.workVariant=['Cinematic','Gallery'].includes(v)?'Stacked':'Grid'}
function updateField(id,value,rerender=true){if(id==='project.visibility'&&value==='Password protected'){upgrade('Password protection');render();return}if(id.endsWith('.url')&&value&&!/^https:\/\//i.test(value)){toast('Use an https:// video link.');return}if(id==='accent'&&!/^#[0-9a-f]{6}$/i.test(value))return;const dialogOpen=$('#dialog').open;mutate(()=>{if(id.startsWith('profile.'))state.profile[id.split('.')[1]]=value;else if(id.startsWith('publish.'))state.publish[id.split('.')[1]]=value;else if(id.startsWith('project.'))getProject()[id.split('.')[1]]=value;else if(id.startsWith('section.'))state.sections.find(s=>s.id===id.split('.')[1]).text=value;else if(id.startsWith('block.')){const [_,bid,key]=id.split('.');getProject().blocks.find(b=>b.id===bid)[key]=value}else if(id==='style')applyFamily(value);else state[id]=value},rerender&&!dialogOpen)}
async function readImage(file){if(!file||!/^image\/(png|jpeg|webp)$/.test(file.type))throw new Error('Choose a PNG, JPG, or WebP image.');if(file.size>3*1024*1024)throw new Error('Please choose an image smaller than 3 MB.');const data=await new Promise((resolve,reject)=>{const r=new FileReader();r.onload=()=>resolve(r.result);r.onerror=reject;r.readAsDataURL(file)});return await new Promise((resolve,reject)=>{const img=new Image();img.onload=()=>{const canvas=document.createElement('canvas'),scale=Math.min(1,1600/img.width);canvas.width=img.width*scale;canvas.height=img.height*scale;canvas.getContext('2d').drawImage(img,0,0,canvas.width,canvas.height);resolve(canvas.toDataURL('image/jpeg',.82))};img.onerror=()=>reject(new Error('This image could not be read.'));img.src=data})}
document.addEventListener('click',e=>{const el=e.target.closest('[data-action]');if(el){const [a,...v]=el.dataset.action.split(':');handleExtraAction(a,v.join(':'))}});
document.addEventListener('change',async e=>{const t=e.target;try{if(t.hasAttribute('data-filter')){filter=t.value;render()}if(t.dataset.feature){mutate(()=>{state.projects.find(p=>p.id===t.dataset.feature).featured=t.checked},!$('#dialog').open)}if(t.dataset.publishCheck)mutate(()=>state.publish[t.dataset.publishCheck]=t.checked,false);if(t.hasAttribute('data-upload-asset')){const url=await readImage(t.files[0]);mutate(()=>state.assets.push({name:t.files[0].name,url}));assets();toast('Image added to your assets.')}if(t.hasAttribute('data-hero-image')){const data=await readImage(t.files[0]);mutate(()=>state.heroImage=data);closeModal();toast('Hero image updated.',true)}if(t.hasAttribute('data-replace-cover')){const data=await readImage(t.files[0]);mutate(()=>getProject().cover=data);closeModal();toast('Cover updated.',true)}if(t.dataset.blockImage||t.dataset.blockSecond){const data=await readImage(t.files[0]);mutate(()=>{const b=getProject().blocks.find(b=>b.id===(t.dataset.blockImage||t.dataset.blockSecond));b[t.dataset.blockSecond?'secondImage':'image']=data},false);toast('Image saved.')}}catch(err){toast(err.message)}});
let fieldGroup={id:null,time:0};
document.addEventListener('input',e=>{const t=e.target;if(t.dataset.field&&t.tagName!=='SELECT'){const group=t.dataset.field===fieldGroup.id&&Date.now()-fieldGroup.time<1200;updateField(t.dataset.field,t.value,false);if(group&&history.length>1)history.pop();fieldGroup={id:t.dataset.field,time:Date.now()};document.querySelectorAll('[data-action="undo"]').forEach(b=>b.disabled=!history.length);const canvas=$('.canvas-wrap .portfolio');if(canvas)canvas.outerHTML=portfolio(true);const title=$('.search-preview strong');if(title){title.textContent=state.publish.seoTitle;$('.search-preview p').textContent=state.publish.description;$('.search-preview span').textContent=state.publish.slug+'.sitofolio.com'}}if(t.hasAttribute('data-search')){query=t.value;const start=t.selectionStart;render();const input=$('[data-search]');input.focus();input.setSelectionRange(start,start)}if(t.hasAttribute('data-ai-draft'))aiDraft=t.value});
document.addEventListener('focusout',e=>{if(e.target.dataset.caseEdit)mutate(()=>getProject()[e.target.dataset.caseEdit]=e.target.innerText.trim(),false);if(e.target.dataset.blockEdit)mutate(()=>getProject().blocks.find(b=>b.id===e.target.dataset.blockEdit).text=e.target.innerText.trim(),false)});
document.addEventListener('submit',async e=>{if(e.target.id==='quick-form'){e.preventDefault();const form=new FormData(e.target);let image;try{image=form.get('cover').size?await readImage(form.get('cover')):initial.projects[0].cover}catch(err){toast(err.message);return}const id=crypto.randomUUID();mutate(()=>state.projects.push({id,title:form.get('title').trim(),type:form.get('type'),year:form.get('year'),role:form.get('role')||'Design',notes:form.get('notes'),cover:image,status:'Draft',visibility:'Public',featured:true,blocks:[{id:crypto.randomUUID(),type:'Project Intro',text:form.get('notes'),visible:true}]}));closeModal();if(view!=='onboarding'){projectId=id;aiDraft='';go('project')}else render();toast('Project created. Build the story at your own pace.')}if(e.target.id==='publish-form'){e.preventDefault();if(!/^[a-z0-9]+(?:-[a-z0-9]+)*$/.test(state.publish.slug)||state.publish.slug.length>30){toast('Use 1–30 lowercase letters or numbers, with hyphens between words.');return}if(!state.publish.seoTitle.trim()){toast('Add a page title before publishing.');return}mutate(()=>{state.publish.status='Published';state.publish.last=new Date().toISOString();const snapshot=structuredClone({...state,publish:{...state.publish,snapshot:null}});snapshot.projects=snapshot.projects.filter(p=>p.status==='Published'&&p.visibility==='Public');state.publish.snapshot=snapshot});modal('Looks good. You’re out there.',`<div class="success-icon">${icon('check')}</div><p>Your portfolio has a published snapshot.</p><div class="published-address">${esc(state.publish.slug)}.sitofolio.com</div><p class="help-tip">This is a simulated publish. The address is illustrative; nothing has been deployed. Your next edits will stay in draft until you publish again.</p>`,btn('View published snapshot','published-preview','primary')+btn('Back to workspace','published-done'));}});
document.addEventListener('click',e=>{const a=e.target.closest('[data-action]')?.dataset.action;if(a==='published-done'){closeModal();go('overview')}if(a==='published-preview')closeModal()});
document.addEventListener('keydown',e=>{const typing=e.target.matches('input,textarea,select,[contenteditable]');if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='z'&&!typing){e.preventDefault();e.shiftKey?redo():undo()}if(e.key==='Enter'&&e.target.dataset.section){selected=e.target.dataset.section;render()}if(e.key==='Enter'&&e.target.dataset.action&&e.target.tagName!=='BUTTON'){e.preventDefault();e.target.click()}if(e.target.isContentEditable&&e.key==='Escape')e.target.blur()});
let dragItem=null;
document.addEventListener('dragstart',e=>{const el=e.target.closest('[data-drag-section],[data-drag-block]');if(el){dragItem={kind:el.dataset.dragSection?'section':'block',id:el.dataset.dragSection||el.dataset.dragBlock};e.dataTransfer.effectAllowed='move';e.dataTransfer.setData('text/plain',dragItem.id)}});
document.addEventListener('dragover',e=>{if(e.target.closest('[data-drag-section],[data-drag-block]'))e.preventDefault()});
document.addEventListener('drop',e=>{const el=e.target.closest('[data-drag-section],[data-drag-block]');if(!el||!dragItem)return;e.preventDefault();const id=el.dataset.dragSection||el.dataset.dragBlock;if(id===dragItem.id)return;mutate(()=>{const a=dragItem.kind==='section'?state.sections:getProject().blocks;const from=a.findIndex(s=>s.id===dragItem.id),to=a.findIndex(s=>s.id===id);if(from>=0&&to>=0)a.splice(to,0,a.splice(from,1)[0])});dragItem=null;toast('Order updated.',true)});
window.addEventListener('hashchange',()=>{view=location.hash.slice(1)||'editor';render()});
// A small optional agent interface uses exactly the same actions as the UI.
if(document.modelContext?.registerTool){for(const tool of [{name:'read_portfolio_prototype',title:'Read portfolio prototype',description:'Read the current local prototype state without changing it.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true,untrustedContentHint:true},execute:()=>({view,style:state.style,name:state.profile.name,projects:state.projects.map(({id,title,status})=>({id,title,status})),publishStatus:state.publish.status})},{name:'navigate_portfolio_prototype',title:'Open prototype screen',description:'Navigate to a local prototype screen. Does not publish or change portfolio content.',inputSchema:{type:'object',properties:{screen:{type:'string',enum:['overview','editor','projects','onboarding','preview','publish']}},required:['screen'],additionalProperties:false},annotations:{readOnlyHint:false,untrustedContentHint:false},execute:({screen})=>{if(!['overview','editor','projects','onboarding','preview','publish'].includes(screen))throw new Error('Unknown screen');go(screen);return{screen:view}}}]){try{Promise.resolve(document.modelContext.registerTool(tool)).catch(()=>{})}catch{}}}
const routeRender=render;let lastRenderedView=null;
render=function(){const selectors=['.canvas-wrap','.right-panel','.left-panel','.builder-canvas','.preview-canvas','.publish-panel'];const offsets=lastRenderedView===view?selectors.map(s=>[s,$(s)?.scrollTop||0]):[];routeRender();for(const [s,y] of offsets)if($(s))$(s).scrollTop=y;lastRenderedView=view};
const plainPreview=preview;
preview=function(){let html=plainPreview();html=html.replace('<div class="grow"></div>',`<div class="grow"></div>${btn('Review link','preview-link','quiet')}`);if(view==='publish'){const ready=state.projects.filter(p=>p.status==='Published'&&p.visibility==='Public').length;html=html.replace('<div class="publish-status">',`<p class="help-tip" style="margin-top:18px">${ready} public, published projects will be included. Draft, hidden, archived, and private projects stay out of the published snapshot.</p><div class="publish-status">`);if(state.publish.status==='Published')html=html.replace('</form>',`</form>${btn('Unpublish portfolio','unpublish','quiet full')}`)}return html};
document.addEventListener('click',e=>{if(e.target.closest('[data-action="unpublish"]')){mutate(()=>{state.publish.status='Unpublished';state.publish.snapshot=null;state.publish.last=null});toast('Portfolio unpublished.',true)}const block=e.target.closest('[data-case-block]');if(block&&!e.target.closest('button,[contenteditable]')){selectedBlock=block.dataset.caseBlock;document.querySelectorAll('.case-block').forEach(el=>el.classList.toggle('selected',el===block))}});
render();
